/// Gets the Script for a code point
pub fn getScript(cp: Codepoint) Script {
    if (cp > 0x10FFFF) return .Unknown;
    const block = @as(usize, cp >> 8);
    if (block >= script_stage1.len) return .Unknown;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = script_stage1[block] + offset;
    if (stage2_idx >= script_stage2.len) return .Unknown;
    return @enumFromInt(script_stage2[stage2_idx]);
}

/// Checks if a code point belongs to a specific script
pub fn isScript(cp: Codepoint, script: Script) bool {
    return getScript(cp) == script;
}

/// Checks if a string contains only characters from the given script (plus Common/Inherited)
pub fn isScriptHomogeneous(text: []const u8, script: Script) bool {
    const std = @import("std");
    var iter = std.unicode.Utf8Iterator{ .bytes = text, .i = 0 };
    while (iter.nextCodepoint()) |cp| {
        const s = getScript(cp);
        if (s != script and s != .Common and s != .Inherited) {
            return false;
        }
    }
    return true;
}
